SET local check_function_bodies = off;

CREATE TABLE "public"."profiles" (
  "id"        uuid                     NOT NULL,
  "nombre"    character varying(100)   NOT NULL,
  "creado_en" timestamp with time zone DEFAULT now(),
  CONSTRAINT "profiles_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."profiles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."proyecto" (
  "id_proyecto"  bigint                 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_usuario"   uuid                   NOT NULL,
  "nombre"       character varying(150) NOT NULL,
  "descripcion"  text,
  "fecha_inicio" date                   NOT NULL,
  "fecha_fin"    date,
  CONSTRAINT "proyecto_pkey" PRIMARY KEY (id_proyecto)
);

ALTER TABLE "public"."proyecto"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."tarea_usuario" (
  "id_proyecto"  bigint  NOT NULL,
  "numero_tarea" integer NOT NULL,
  "id_usuario"   uuid    NOT NULL,
  CONSTRAINT "tarea_usuario_pkey" PRIMARY KEY (id_proyecto, numero_tarea, id_usuario)
);

ALTER TABLE "public"."tarea_usuario"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."tarea" (
  "id_proyecto"              bigint                NOT NULL,
  "numero_tarea"             integer               NOT NULL,
  "codigo_tarea"             character varying(35) GENERATED ALWAYS AS ((((id_proyecto)::text || '-'::text) || lpad((numero_tarea)::text, 4, '0'::text))) STORED,
  "fecha_inicio"             date                  NOT NULL,
  "fecha_fin"                date,
  "complejidad"              character varying(50) NOT NULL,
  "estado"                   character varying(50) NOT NULL DEFAULT 'Pendiente'::character varying,
  "numero_tarea_predecesora" integer,
  CONSTRAINT "tarea_pkey" PRIMARY KEY (id_proyecto, numero_tarea)
);

ALTER TABLE "public"."tarea"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.fn_asignar_numero_tarea()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
DECLARE
    v_siguiente_numero INT;
BEGIN
    PERFORM 1 FROM public.proyecto WHERE id_proyecto = NEW.id_proyecto FOR UPDATE;

    SELECT COALESCE(MAX(numero_tarea), 0) + 1
    INTO v_siguiente_numero
    FROM public.tarea
    WHERE id_proyecto = NEW.id_proyecto;

    NEW.numero_tarea := v_siguiente_numero;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  AS $function$
BEGIN
    INSERT INTO public.profiles (id, nombre)
    VALUES (
        NEW.id,
        COALESCE(NEW.raw_user_meta_data->>'nombre', 'Nuevo Usuario')
    );
    RETURN NEW;
END;
$function$;

ALTER TABLE "public"."profiles"
  ADD CONSTRAINT "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;

ALTER TABLE "public"."proyecto"
  ADD CONSTRAINT "proyecto_id_usuario_fkey" FOREIGN KEY (id_usuario) REFERENCES public.profiles(id) ON DELETE CASCADE;

ALTER TABLE "public"."tarea"
  ADD CONSTRAINT "tarea_id_proyecto_fkey" FOREIGN KEY (id_proyecto) REFERENCES public.proyecto(id_proyecto) ON DELETE CASCADE;

ALTER TABLE "public"."tarea"
  ADD CONSTRAINT "fk_tarea_predecesora" FOREIGN KEY (id_proyecto, numero_tarea_predecesora) REFERENCES public.tarea(id_proyecto, numero_tarea) ON DELETE SET NULL;

ALTER TABLE "public"."tarea_usuario"
  ADD CONSTRAINT "tarea_usuario_id_proyecto_numero_tarea_fkey" FOREIGN KEY (id_proyecto, numero_tarea) REFERENCES public.tarea(id_proyecto, numero_tarea) ON DELETE CASCADE;

ALTER TABLE "public"."tarea_usuario"
  ADD CONSTRAINT "tarea_usuario_id_usuario_fkey" FOREIGN KEY (id_usuario) REFERENCES public.profiles(id) ON DELETE CASCADE;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

CREATE TRIGGER trg_asignar_numero_tarea
  BEFORE INSERT ON public.tarea
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_asignar_numero_tarea();

CREATE POLICY "Los usuarios pueden actualizar su propio perfil" ON "public"."profiles"
  FOR UPDATE
  TO PUBLIC
  USING ((auth.uid() = id));

CREATE POLICY "Los usuarios pueden ver su propio perfil" ON "public"."profiles"
  FOR SELECT
  TO PUBLIC
  USING ((auth.uid() = id));

CREATE POLICY "Gestión total de sus propios proyectos" ON "public"."proyecto"
  FOR ALL
  TO PUBLIC
  USING ((auth.uid() = id_usuario))
  WITH CHECK ((auth.uid() = id_usuario));

CREATE POLICY "Gestión de tareas en proyectos propios" ON "public"."tarea"
  FOR ALL
  TO PUBLIC
  USING ((EXISTS ( SELECT 1
   FROM public.proyecto p
  WHERE ((p.id_proyecto = tarea.id_proyecto) AND (p.id_usuario = auth.uid())))))
  WITH CHECK ((EXISTS ( SELECT 1
   FROM public.proyecto p
  WHERE ((p.id_proyecto = tarea.id_proyecto) AND (p.id_usuario = auth.uid())))));

CREATE POLICY "Gestión de asignaciones en proyectos propios" ON "public"."tarea_usuario"
  FOR ALL
  TO PUBLIC
  USING ((EXISTS ( SELECT 1
   FROM public.proyecto p
  WHERE ((p.id_proyecto = tarea_usuario.id_proyecto) AND (p.id_usuario = auth.uid())))))
  WITH CHECK ((EXISTS ( SELECT 1
   FROM public.proyecto p
  WHERE ((p.id_proyecto = tarea_usuario.id_proyecto) AND (p.id_usuario = auth.uid())))));

GRANT EXECUTE ON FUNCTION "public"."fn_asignar_numero_tarea"() TO PUBLIC, "anon", "authenticated";

REVOKE ALL ON FUNCTION "public"."fn_asignar_numero_tarea"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."fn_asignar_numero_tarea"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."fn_asignar_numero_tarea"() TO "service_role";

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO PUBLIC, "anon", "authenticated";

REVOKE ALL ON FUNCTION "public"."handle_new_user"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."handle_new_user"() TO "service_role";

REVOKE ALL ON SEQUENCE "public"."proyecto_id_proyecto_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."proyecto_id_proyecto_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."proyecto_id_proyecto_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."proyecto_id_proyecto_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."proyecto_id_proyecto_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."proyecto_id_proyecto_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."proyecto_id_proyecto_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."proyecto_id_proyecto_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."profiles" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."profiles" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."profiles" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."profiles" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."proyecto" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."proyecto" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."proyecto" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."proyecto" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."tarea" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."tarea" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."tarea" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."tarea" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."tarea_usuario" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."tarea_usuario" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."tarea_usuario" TO "postgres";

